            rtype = r.get("type", "")
            source = r.get("source", "")
            extra = [p for p in [r.get("model_type", ""), r.get("base_model", "")] if p]
            if extra:
                rtype = f"{rtype} ({', '.join(extra)})" if rtype else ", ".join(extra)
            status = "[green]installed[/green]" if r.get("installed") else ""
            table.add_row(name, rtype, source, status)
